import { edit_get_leave_approvals } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import SnackBar from "@/components/SnackBar.vue";
export default {
  mixins: [get_all_org_users
  // update_audit_logs
  ],
  components: {
    SnackBar
  },
  data() {
    return {
      addData: false,
      stepType: null,
      rolesRM: false,
      loading: false,
      initiaorRM: null,
      initiaorCheck: null,
      teamMember: null,
      teamMemberSelected: "",
      selectTeam: [],
      userArray: [],
      searchF: "",
      SnackBarComponent: {},
      selectedData: [],
      flowSteps: [{
        selected: false,
        text: "Initiator"
      }, {
        selected: false,
        text: "Initiator's Reporting Manager"
      }, {
        selected: false,
        text: "Roles"
      }],
      finalArray: [],
      addedRecords: [],
      listSelected: [],
      roleSelected: "",
      itemSelIndex: 0,
      userList: [],
      workflowList: [],
      formObject: {},
      inputRecords: [],
      tableData: [],
      templete: [],
      workflowTemplate: [],
      search: "",
      groupheadNotification: false,
      dialogSteps: [{
        label: "Initiator's Reporting Manager",
        value: "repotingManager",
        model: "initiaorRM"
      }, {
        label: "Team Member",
        value: "member_team",
        model: "teamMember"
      }]
    };
  },
  async created() {
    this.$store.commit("Setnamesearch", this.search);
    await this.get_all_org_users();
    await this.fetch_users();
    await this.get_initiated_expense();
  },
  watch: {
    addData: {
      async handler() {
        // await this.get_all_org_users();
      }
    },
    teamMemberSelected(newVal) {}
  },
  methods: {
    async save_expense_head() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_get_leave_approvals, {
          input: {
            is_group_noftication_enabled: this.groupheadNotification,
            notifications: this.selectTeam,
            action_type: "CREATE",
            organization_id: data.organization.organization_id,
            workflow_approval_steps: JSON.stringify(this.addedRecords)
          }
        }));
        var response = JSON.parse(result.data.edit_get_leave_approvals);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
          this.get_initiated_expense();
          // this.fetch_audit_message();
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
        this.loading = false;
      }
    },
    fetch_users() {
      this.userList = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userList.push({
            title: element.full_user_name,
            user_id: element.user_id
          });
        }
      });
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userArray.push({
            title: element.full_user_name,
            user_id: element.user_email_id
          });
        }
      });
      this.userList.sort((a, b) => a.title.localeCompare(b.title));
    },
    delete_record(val) {
      this.addedRecords.splice(val, 1);
      this.stepType = null;
      this.initiaorRM = null;
      this.initiaorCheck = null;
      this.rolesRM = false;
      this.roleSelected = "";
    },
    close_dialog() {
      this.addData = false;
      this.initiaorRM = null;
      this.initiaorCheck = null;
      this.rolesRM = false;
      this.roleSelected = "";
      this.inputRecords = [];
    },
    add_row(value) {
      this.inputRecords = [];
      this.teamMember = null;
      this.initiaorCheck = null;
      this.initiaorRM = null;
      this.itemSelIndex = value;
      this.addData = true;
    },
    add_dialog() {
      this.inputRecords = [];
      this.teamMember = null;
      this.initiaorCheck = null;
      this.initiaorRM = null;
      this.addData = true;
    },
    add_items() {
      if (!this.stepType) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Please select a step type",
          timeout: 5000,
          Top: true
        };
        return;
      }
      if (this.stepType === "member_team" && !this.teamMemberSelected) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Please select a team member",
          timeout: 5000,
          Top: true
        };
        return;
      }
      let newStep;
      if (this.stepType === "repotingManager") {
        newStep = {
          step_no: this.addedRecords.length + 1,
          name: "Initiator's Reporting Manager",
          user_type: "initiator_reporting_manager",
          workflow_template: this.workflowTemplate
        };
      } else if (this.stepType === "member_team") {
        if (!this.teamMemberSelected || !this.teamMemberSelected.user_id) {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: "Selected team member has no user_id!",
            timeout: 5000,
            Top: true
          };
          return;
        }
        newStep = {
          step_no: this.addedRecords.length + 1,
          name: this.teamMemberSelected.title,
          user_id: this.teamMemberSelected.user_id,
          user_type: "team_member",
          workflow_template: this.workflowTemplate
        };
      }
      this.addedRecords.push(newStep);
      this.addData = false;
      this.stepType = null;
      this.teamMemberSelected = null;
    },
    get_input(index) {
      var count = 0;
      var data = [];
      this.inputRecords = [];
      if (index == 0 && index != undefined) {
        this.inputRecords.push({
          step_no: this.addedRecords.length + 1,
          name: "Initiator's Reporting Manager",
          // user_id: undefined,
          user_type: "initiator_reporting_manager",
          workflow_template: this.workflowTemplate
          // workflow_template: this.workflowTemplate,
          // name: "Initiator Reporting Manager",
          // value: "initiator_reporting_manager",
          // key: "initiator_reporting_manager",
          // formDetails: this.workflowTemplate,
        });
        this.initiaorRM = "repotingManager";
        this.initiaorCheck = null;
        this.rolesRM = false;
        this.teamMember = null;
      } else if (index == 1 && index != undefined) {
        this.inputRecords.push({
          step_no: this.addedRecords.length + 1,
          name: this.teamMemberSelected.full_user_name,
          user_id: this.teamMemberSelected.user_id,
          user_type: "team_member",
          workflow_template: this.workflowTemplate
        });
        this.teamMember = "member_team";
        this.initiaorCheck = null;
        this.initiaorRM = null;
        this.rolesRM = false;
      }
      this.finalArray = this.inputRecords;
    },
    async get_initiated_expense() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_get_leave_approvals, {
          input: {
            action_type: "GET",
            // workflow_approval_steps:
            // user_email_id: data.user.user_email_id,
            organization_id: data.organization.organization_id
          }
        }));
        var response = JSON.parse(result.data.edit_get_leave_approvals);
        if (response.Status == "SUCCESS") {
          this.groupheadNotification = response.data.is_group_noftication_enabled == undefined ? false : this.groupheadNotification = response.data.is_group_noftication_enabled;
          this.selectTeam = response.data.notifications == undefined ? [] : response.data.notifications;
          this.workflowTemplate = response.data.workflow_template;
          this.tableData = response.data;
          this.addedRecords = this.tableData.workflow_approval_steps;
          // console.log( this.addedRecords);
          if (this.addedRecords.length > 0) {
            for (let s = 0; s < this.addedRecords.length; s++) {
              let name = this.orgUsers.filter(x => x.user_id == this.addedRecords[s].user_id);
              this.addedRecords[s].name = name.length > 0 ? name[0].full_user_name : "Initiator's Reporting Manager";
            }
          }
        } else {
          this.tableData = [];
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    async fetch_audit_message() {
      var data = this.$store.getters.GetUserObj;
      var data = {
        AuditType: "PREZENCE",
        AuditAction: "PREZENCE_LEAVE_APPROVAL",
        AuditMessage: `${data.user.full_user_name} Updated Presence Leave Approval`
      };
      this.$store.commit("SetAuditActions", data);
      // this.update_audit_logs();
    }
  }
};
